const embedding = $input.first().json.data[0].embedding;

// Query SMEKnowledge nodes directly by vector similarity
const smeQuery = JSON.stringify({
  statements: [{
    statement: "CALL db.index.vector.queryNodes('atlas_chunk_embeddings', 5, $embedding) YIELD node, score WHERE 'SMEKnowledge' IN labels(node) RETURN node.question AS question, node.answer AS answer, node.topic AS topic, node.confidence AS confidence, score ORDER BY score DESC",
    parameters: { embedding: embedding }
  }]
});

return [{ json: { requestBody: smeQuery, embedding: embedding } }];

const embedding = $('Embed Question').first().json.data[0].embedding;

// Query DocChunk nodes for supporting documentation context
const docQuery = JSON.stringify({
  statements: [{
    statement: "CALL db.index.vector.queryNodes('atlas_chunk_embeddings', 3, $embedding) YIELD node, score WHERE 'DocChunk' IN labels(node) RETURN node.heading AS heading, node.text AS text, node.title AS title, score ORDER BY score DESC",
    parameters: { embedding: embedding }
  }]
});

return [{ json: { requestBody: docQuery } }];

const question = $('Webhook').first().json.body.question;

// Build SME context
const smeRows = $('Query SMEKnowledge').first().json.results[0].data;
const smeChunks = smeRows.map(row => ({
  question: row.row[0],
  answer: row.row[1],
  topic: row.row[2],
  confidence: row.row[3],
  score: row.row[4]
})).filter(s => s.score > 0.6);

let smeContext = '';
if (smeChunks.length > 0) {
  smeContext = smeChunks
    .map(s => `**[SME — ${s.topic} · ${s.confidence}]**\nQ: ${s.question}\nA: ${s.answer}`)
    .join('\n\n---\n\n');
}

// Build doc context
const docRows = $input.first().json.results[0].data;
const docChunks = docRows.map(row => ({
  heading: row.row[0],
  text: row.row[1],
  title: row.row[2],
  score: row.row[3]
})).filter(d => d.score > 0.5);

let docContext = '';
if (docChunks.length > 0) {
  docContext = docChunks
    .map(d => `**[Docs — ${d.title} · ${d.heading}]**\n${d.text}`)
    .join('\n\n---\n\n');
}

const hasSME = smeChunks.length > 0;
const hasDocs = docChunks.length > 0;

return [{ json: { question, smeContext, docContext, hasSME, hasDocs } }];

